with base as (select *, datediff(current_date(), order_date) / 365 as years_since_order_date, coalesce(channel, 'DIRECT') as resolved_channel from orders where customer_id is not null and order_date >= to_date('2023-07-03')), with_windows as (select id, customer_id, store_id, amount, discount, shipping_fee, rank() over (partition by customer_id order by discount desc nulls first) as discount_rank, lag(shipping_fee, 1, 0) over w_running as prev_shipping_fee from base window w_running as (partition by channel order by amount, id)), ranked as (select id, customer_id, discount, prev_shipping_fee from with_windows qualify row_number() over (partition by store_id order by shipping_fee desc, id) = 1), enriched as (select s.*, c.city, c.segment, c.name from ranked s inner join customers c on s.customer_id <=> c.id), metrics as (select *, lead(discount) over w_part as next_discount, lag(discount) over w_part as prev_discount, lag(prev_shipping_fee) over w_part as prev_prev_shipping_fee, lead(prev_shipping_fee) over w_part as next_prev_shipping_fee, row_number() over w_part as seq_no from enriched where prev_shipping_fee <= 33 window w_part as (partition by customer_id, segment order by prev_shipping_fee, id)), stats as (select city, count(*) filter (where segment = 'Corporate') as corporate_rows, count(case when segment = 'SMB' then 1 end) as smb_count, count(distinct city) as distinct_cities, count(distinct id) as distinct_ids, approx_percentile(prev_discount, array(0.25, 0.5, 0.75)) as prev_discount_quartiles, count(case when city = 'Singapore' then 1 end) as singapore_count from metrics group by city having count(distinct id) < 1000) select city, smb_count, distinct_cities, distinct_ids, prev_discount_quartiles from stats order by city nulls first;
